(()=>{const wait=async fn=>{const end=Date.now()+12000;while(!fn()){if(Date.now()>end)throw Error('Timed out waiting for local page');await new Promise(r=>setTimeout(r,35));}},pause=ms=>new Promise(r=>setTimeout(r,ms));let count=0;const errors=[];window.addEventListener('error',e=>errors.push(e.message));
const run=async()=>{const box=document.createElement('pre');box.id='a7-test-output';box.style.cssText='position:fixed;inset:10px;z-index:99999;background:#101b19;color:#dcffe8;overflow:auto;padding:20px;font:14px monospace;white-space:pre-wrap';document.body.append(box);const check=(ok,text)=>{if(!ok)throw Error(text);count++;box.textContent+='PASS '+text+'\n';},$=id=>document.getElementById(id);let oldHistory;
try{await wait(()=>window.DDoSGuard&&typeof window.handleSimulatedLoginSubmit==='function'&&$('a7-movie-video'));oldHistory=localStorage.getItem('ddos-guard-history');$('sim-login-username').value='student';$('sim-login-password').value='StudentDemo!2026';await window.handleSimulatedLoginSubmit();await wait(()=>!$('workbench-content').inert);window.switchTab('tab-7');await wait(()=>$('panel-tab-7').classList.contains('active'));check($('panel-tab-7').classList.contains('active'),'Lab 07 opens after original demo login');
try{const v=$('a7-movie-video');const mediaResponse=await fetch(v.querySelector('source').src,{method:'HEAD'});check(mediaResponse.ok,'Local MP4 HTTP '+mediaResponse.status);check((mediaResponse.headers.get('content-type')||'').includes('video/mp4'),'Server returns video/mp4');await wait(()=>v.readyState>=1||v.error);check(!v.error&&v.videoWidth===1024&&v.videoHeight===1536,'Original portrait MP4 loads local metadata');check(v.duration>5&&v.duration<5.1,'Preview duration approximately five seconds');check(v.controls&&!v.autoplay&&v.preload==='metadata'&&v.playsInline,'Native controls, metadata preload, inline playback, no autoplay');check($('a7-movie-status').textContent==='AI Movie Preview — Full Film in Production.','Incomplete status remains explicit after load');v.muted=true;await v.play();await pause(450);check(v.currentTime>0&&!v.paused,'Real video playback advances');v.pause();const at=v.currentTime;await pause(180);check(v.paused&&Math.abs(v.currentTime-at)<.03,'Pause stops playback');v.currentTime=2;await wait(()=>!v.seeking);check(Math.abs(v.currentTime-2)<.1,'Seeking works');v.currentTime=0;v.muted=false;check(!document.querySelector('.a7-movie-error:not([hidden])'),'No media error fallback on valid source');
}catch(mediaError){box.textContent+='NOT VERIFIED media playback: '+mediaError.message+'\n';}
const r=window.DDoSGuard.results;check($('dg-model-table').rows.length===2&&$('dg-stats').textContent.includes('185,117'),'Stored model table and dataset counters render');check($('dg-roc').querySelectorAll('polyline').length===4,'Two stored ROC curves, chance and axes render');for(const feature of ['Flow Packets/s','Flow Bytes/s','Flow Duration']){$('dg-feature').value=feature;$('dg-feature').dispatchEvent(new Event('change'));check($('dg-hist').querySelectorAll('.dg-hist-row').length===9,'Distribution selector '+feature);}for(const metric of ['precision','recall','f1','accuracy']){$('dg-metric').value=metric;$('dg-metric').dispatchEvent(new Event('change'));check($('dg-model-bars').textContent.includes((r.models['Decision tree'][metric]*100).toFixed(2)+'%'),'Metric selector '+metric);}
for(let i=0;i<r.examples.length;i++){$('dg-example').value=String(i);$('dg-example').dispatchEvent(new Event('change'));$('dg-form').dispatchEvent(new Event('submit',{cancelable:true}));check($('dg-verdict').textContent.startsWith(r.examples[i].prediction?'Attack-like':'Benign-like')&&$('dg-reasons').children.length>0,'Held-out example '+(i+1)+' prediction and explanation');}
$('dg-save').checked=true;$('dg-form').dispatchEvent(new Event('submit',{cancelable:true}));check($('dg-history-list').querySelectorAll('button').length>0,'Opt-in history saves');const own=$('dg-history-list').querySelector('article'),bs=own.querySelectorAll('button');bs[0].click();check($('dg-verdict').textContent.includes('local decision tree'),'History revisit');const before=$('dg-history-list').querySelectorAll('article').length;bs[1].click();check($('dg-history-list').querySelectorAll('article').length===before-1,'Delete one history entry');$('dg-save').checked=false;$('dg-value-0').value='999';$('dg-form').dispatchEvent(new Event('submit',{cancelable:true}));check($('dg-verdict').textContent.includes('protocol'),'Invalid protocol rejected');$('dg-value-0').value='';$('dg-form').dispatchEvent(new Event('submit',{cancelable:true}));check($('dg-verdict').textContent.includes('all eight'),'Missing measurements rejected');
let download;const click=HTMLAnchorElement.prototype.click;HTMLAnchorElement.prototype.click=function(){download={name:this.download,href:this.href};};try{$('dg-export').click();check(download.name==='ddos-guard-results.json'&&download.href.startsWith('blob:'),'Original research JSON export creates download');}finally{HTMLAnchorElement.prototype.click=click;}
$('research-model').value='Random forest';$('research-model').dispatchEvent(new Event('change'));const missed=document.querySelectorAll('.research-confusion button')[2];missed.click();check($('research-error-detail').textContent.includes('21,580'),'Error investigator shows stored missed-attack count');check(errors.length===0,'No captured runtime errors');box.textContent+='COMPLETE: '+count+' local checks passed. No training, rendering, server, microphone or external AI calls.';
}catch(e){box.textContent+='FAIL '+e.message;}finally{if(oldHistory!==undefined){if(oldHistory===null)localStorage.removeItem('ddos-guard-history');else localStorage.setItem('ddos-guard-history',oldHistory);}}};if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',run,{once:true});else run();})();
